$ErrorActionPreference = "Stop"
$root = (Get-Location).Path
$backup = Join-Path $root (".security-backup/" + [guid]::NewGuid().ToString())
if ((Get-FileHash -LiteralPath (Join-Path $root "agent/nodes.py")).Hash -ne "cc5376cc998cb74831296a928ca13e75e9d1c3fc0e5bbf772f8f9cdd7cbfa98a") { throw "Original file differs: agent/nodes.py" }
if ((Get-FileHash -LiteralPath (Join-Path $root "agent/routing.py")).Hash -ne "fb5690b7b374a3c85ddd93811afe90765ca3ba2c3806aed486c2fa7dd0309b7e") { throw "Original file differs: agent/routing.py" }
if ((Get-FileHash -LiteralPath (Join-Path $root "domain/policies.py")).Hash -ne "594e234d2737c570ea18250864b97492f62e14f8cc7f9dd4916e0b58627fa038") { throw "Original file differs: domain/policies.py" }
if ((Get-FileHash -LiteralPath (Join-Path $root "tests/test_domain.py")).Hash -ne "67a836a5a03bcd4e7004dc31fc1911c5121aca02e98625e540363e0912bc91db") { throw "Original file differs: tests/test_domain.py" }
try {
$p = Join-Path $root "agent/nodes.py"
$b = Join-Path $backup "agent/nodes.py"
New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null
Copy-Item -LiteralPath $p -Destination $b
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(""))
$p = Join-Path $root "agent/routing.py"
$b = Join-Path $backup "agent/routing.py"
New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null
Copy-Item -LiteralPath $p -Destination $b
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(""))
$p = Join-Path $root "domain/policies.py"
$b = Join-Path $backup "domain/policies.py"
New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null
Copy-Item -LiteralPath $p -Destination $b
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(""))
$p = Join-Path $root "tests/test_domain.py"
$b = Join-Path $backup "tests/test_domain.py"
New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null
Copy-Item -LiteralPath $p -Destination $b
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(""))
& .\.venv\Scripts\python.exe -m pytest -q
if ($LASTEXITCODE -ne 0) { throw "Tests failed" }
} catch {
if (Test-Path (Join-Path $backup "agent/nodes.py")) { Copy-Item -LiteralPath (Join-Path $backup "agent/nodes.py") -Destination (Join-Path $root "agent/nodes.py") -Force }
if (Test-Path (Join-Path $backup "agent/routing.py")) { Copy-Item -LiteralPath (Join-Path $backup "agent/routing.py") -Destination (Join-Path $root "agent/routing.py") -Force }
if (Test-Path (Join-Path $backup "domain/policies.py")) { Copy-Item -LiteralPath (Join-Path $backup "domain/policies.py") -Destination (Join-Path $root "domain/policies.py") -Force }
if (Test-Path (Join-Path $backup "tests/test_domain.py")) { Copy-Item -LiteralPath (Join-Path $backup "tests/test_domain.py") -Destination (Join-Path $root "tests/test_domain.py") -Force }
throw
}
Write-Host "Update complete. Backup: $backup"
